def test_escape() -> None:
    pattern = re.compile(r"\\(.*)", re.DOTALL)

    def decode(value: Text) -> Text:
        match = pattern.fullmatch(value)
        assert match is not None
        return escape(match)

    for tail, expected in simple_escapes.items():
        assert decode("\\" + tail) == expected

    assert decode(r"\x00") == "\x00"
    assert decode(r"\x41") == "A"
    assert decode(r"\xff") == "\xff"

    assert decode(r"\0") == "\0"
    assert decode(r"\7") == "\x07"
    assert decode(r"\101") == "A"
    assert decode(r"\377") == "\xff"

    invalid = {
        r"\x": "invalid hex string escape ('\\x')",
        r"\x1": "invalid hex string escape ('\\x1')",
        r"\xGG": "invalid hex string escape ('\\xGG')",
        r"\8": "invalid octal string escape ('\\8')",
        r"\19": "invalid octal string escape ('\\19')",
